 76	    /**
 77	     * The account's current mood as a signed appetite: anger presses the attack, fear presses
 78	     * the save, and the skill band decides how fully the account plays the feeling. The value
 79	     * stays inside [-1, 1] so the opt-in weight alone bounds what a mood can move.
 80	     */
 81	    private function threatAppetite(AiProfile $profile): float
 82	    {
 83	        $now = $this->clock->now();
 84	        $anger = $this->currentAffectIntensity->handle($profile->player_id, AiAffectEmotion::Anger, $now);
 85	        $fear = $this->currentAffectIntensity->handle($profile->player_id, AiAffectEmotion::Fear, $now);
 86	
 87	        return max(-1.0, min(1.0, ($anger - $fear) * $profile->skill_band->evidenceReaction()));
 88	    }
